import heapq

def lex_topo_sort(n: int, edges: list[tuple[int, int]]) -> list[int]:
    adj = [[] for _ in range(n)]
    in_degree = [0] * n

    for u, v in edges:
        adj[u].append(v)
        in_degree[v] += 1

    heap = []
    for i in range(n):
        if in_degree[i] == 0:
            heapq.heappush(heap, (i, in_degree[i]))

    result = []
    while heap:
        node, in_deg = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, (neighbor, in_degree[neighbor]))

    return result if len(result) == n else []
