from collections import deque

def shortest_path_one_break(grid: list[list[int]]) -> int:
    R, C = len(grid), len(grid[0])
    if R == 0 or C == 0:
        return -1

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Initialize BFS
    visited = [[-1 for _ in range(C)] for _ in range(R)]
    queue = deque()

    # Start at (0, 0)
    queue.append((0, 0, 0))  # (row, col, break_count)
    visited[0][0] = 0

    while queue:
        row, col, break_count = queue.popleft()

        if row == R - 1 and col == C - 1:
            return break_count

        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc

            # Check if new position is valid
            if 0 <= new_row < R and 0 <= new_col < C:
                # Check if the cell is a wall (1)
                if grid[new_row][new_col] == 1:
                    # Only allow one wall
                    if break_count == 0:
                        continue
                # Check if we have already passed through a wall
                if grid[new_row][new_col] == 1 and break_count > 0:
                    continue

                # If we haven't used a wall yet, we can go through it
                if grid[new_row][new_col] == 1 and break_count == 0:
                    new_break_count = 1
                else:
                    new_break_count = break_count

                if visited[new_row][new_col] == -1:
                    visited[new_row][new_col] = new_break_count
                    queue.append((new_row, new_col, new_break_count))

    return -1
