def min_subarray_partitions(weights: list[int], k: int) -> int:
    n = len(weights)
    prefix = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix[i] = prefix[i - 1] + weights[i - 1]

    dp = [[0] * (k + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if j == 1:
                dp[i][j] = prefix[i]
            else:
                current_sum = prefix[-1] - prefix[i]
                dp[i][j] = max(dp[i - 1][j - 1], current_sum)

    return dp[n][k]
